+template <class T>
+class gsVisitorSeminormH2
+{
+public:
+
+    gsVisitorSeminormH2(const std::vector< gsMultiPatch<>> & g1):
+        m_G1Basis(g1)
+    {
+        f2param = false;
+        g1basis = true;
+
