         box2(oDir2,1)=box2(oDir2,0);
         box2(oDir2,0)-=scaling*len1;
     }

     return gsAffineFunction<T>(bi.dirMap(bi.first()),bi.dirOrientation(bi.first()) ,box1,box2);
