 // addition of mixed derivative for expressions
 // see https://en.wikipedia.org/wiki/Finite_difference_coefficient
 template <typename T>
 T mixed_derivative(const exprtk::expression<T>& e,
                      T& x, T& y,
                      const double& h = 0.00001)
 {
     T num = T(0.0), tmp;
     T x_init = x;
     T y_init = y;

     x = x_init + T(2.0) * h;
     y = y_init + T(2.0) * h;
     num += e.value();
     y = y_init - T(2.0) * h;
     num -= e.value();
     x = x_init - T(2.0) * h;
     num += e.value();
     y = y_init + T(2.0) * h;
     num -= e.value();

     x = x_init + h;
     y = y_init + h;
     tmp = e.value();
     y = y_init - h;
     tmp -= e.value();
@@ -108,72 +107,72 @@ T mixed_derivative(const exprtk::expression<T>& e,

     x = x_init;
     y = y_init;
