+        gsMultiPatch<> repTop(this->computeAuxTopology());
+        if(auxGeom[0].getOrient())
+        {
+            switch (bInd)
+            {
+                case 3:
+                    break;
+                case 2:
+                    auxGeom[0].rotateParamClock();
+                    break;
+                case 4:
+                    auxGeom[0].rotateParamAntiClockTwice();
+                    break;
+                case 1:
+                    auxGeom[0].rotateParamAntiClock();
+                    break;
+            }
+        }
+        else
+        {
+            switch (bInd)
+            {
+                case 1:
+                    break;
+                case 4:
+                    auxGeom[0].rotateParamClock();
+                    break;
+                case 2:
+                    auxGeom[0].rotateParamAntiClockTwice();
+                    break;
+                case 3:
+                    auxGeom[0].rotateParamAntiClock();
+                    break;
+            }
+        }
+        return this->computeAuxTopology();
+    }
