 void gsFileManagerData::setSearchPaths(const std::string& paths)
 {
     m_paths.clear();

     std::string::const_iterator a;
     std::string::const_iterator b = paths.begin();
     while (true)
     {
         a = b;
         while (b != paths.end() && (*b) != ';') { ++b; }

         std::string p(a,b);

+#if defined _WIN32
