    void uniformRefine_withCoefs(gsMatrix<T>& coefs, int numKnots = 1,  int mul=1)
    {
        assert( coefs.rows() == this->size() && m_weights.rows() == this->size() );
        gsSparseMatrix<T, RowMajor> transfer;
