                ( k2 + 2*refExt >= maxKtIndex ? k2=maxKtIndex-1 : k2+=2*refExt);

                // Store the data...
                refVector[i*offset]       = refLevel;
                refVector[i*offset+1+j]   = k1;
                refVector[i*offset+1+j+d] = k2;
            }
