                 //to try: result(0,i-1) = math::nextafter(result(0,i-1), *result.data() );
-                //#               endif
             }
         }

         itr = end()-1;
         i -= 1;
         if ( result(0,i) > *(itr) )// Ensure that the point is in range
             result(0,i) = *(itr);
     }
