 /// integer power
 inline int ipow(int x, unsigned p)
 {
     if (p == 0) return 1;
     if (p == 1) return x;

     int tmp = ipow(x, p/2);
     if (p % 2 == 0)
         return tmp * tmp;
     else
         return x * tmp * tmp;
 }

