 template<size_t I, class op, typename... Ts>
 void op_tuple_impl (op & _op, const std::tuple<Ts...> &tuple)
 {
     _op(std::get<I>(tuple));
     if (I + 1 < sizeof... (Ts))
         op_tuple_impl<(I+1 < sizeof... (Ts) ? I+1 : I)> (_op, tuple);
 }

 template<class op, typename... Ts>
 void op_tuple (op & _op, const std::tuple<Ts...> &tuple)
 { op_tuple_impl<0>(_op,tuple); }

 template<class T>
 template<class... expr>
 void gsExprAssembler<T>::_computePattern(const expr &... args)
 {
     GISMO_ASSERT(m_fmatrix.cols()==numDofs(), "System not initialized, matrix.cols() = "<<m_fmatrix.cols()<<"!="<<numDofs()<<" = numDofs()");

 #ifdef _OPENMP
     std::vector<omp_lock_t> lock(numDofs());
     for (auto & l : lock)
         omp_init_lock(&l);
 #endif

 #pragma omp parallel
 {
     auto arg_tpl = std::make_tuple(args...);
+
+    // Checks if any of the expressions in args is a matrix
+    // If not, then there is no need to compute sparity patterns
+    // and returns
+    bool isMatrix = false;
+    _checkMatrix CM(isMatrix);
+    op_tuple(CM, arg_tpl);
+    if (!isMatrix) return;
+
     m_exprdata->parsePattern(arg_tpl);

     typename gsBasis<T>::domainIter domItEnd = m_exprdata->domain().endAll();
     unsigned patchInd;
     _pattern pp(m_fmatrix, m_exprdata->points(), patchInd
 #ifdef _OPENMP
                     , lock
 #endif
             );

 #pragma omp for
     for (auto domIt = m_exprdata->domain().beginAll();
         domIt<domItEnd; ++domIt)
     {
         m_exprdata->points() = domIt.centerPoint();
         patchInd = domIt.patch();
         op_tuple(pp, arg_tpl);
     }
 }//parallel
 #ifdef _OPENMP
     for (auto & l : lock)
         omp_destroy_lock(&l);
 #endif
 }

