+void gsBSplineSolver<T>::initSolver(gsBSpline<T,KnotVectorType> const & bsp , 
+                                    int const & coord, T const & tr, 
+                                    T const & tol, unsigned const & N)
+{
+    m_n  = bsp.coefsSize();
+    m_d  = bsp.degree();
+    m_k  = 1;
+    eps  = tol;
+    x    = 0.0;
+    maxn = N + m_n;
