+    m_t.resize(m_n+N+m_d+1); 
+    m_c.resize(m_n+N);  
+
+    for ( unsigned i = 0; i < m_n; ++i ) 
+    {
+        m_c[i]= bsp.coef(i, coord) - tr;
+        m_t[i]= kv[i];
+    }
+  
+    for ( unsigned i = m_n; i < m_n + m_d +1 ; ++i ) 
+        m_t[i]= kv[i];
