inline std::vector<T*> get_raw(const std::vector< shared_ptr<T> >& cont)
{
    std::vector<T*> result;
    for (typename std::vector< shared_ptr<T> >::const_iterator it = cont.begin(); it != cont.end(); ++it)
        result.push_back(const_cast<T*>( (*it).get() ));
    return result;
